class RegistrySingleton(type):
    """
    Metaclass that registers subclasses in a global directory,
    enforces a singleton pattern per subclass, and provides a
    method to reset the singleton instance.
    """
    _subclasses = {}
    _instances = {}

    def __new__(mcs, name, bases, attrs):
        # Create the new class object
        cls = super().__new__(mcs, name, bases, attrs)

        # Register the subclass in the global directory using its name as the key
        mcs._subclasses[name] = cls

        # Define the logic for resetting the singleton instance
        def reset_singleton(cls_ref):
            if cls_ref in mcs._instances:
                del mcs._instances[cls_ref]

        # Attach reset_singleton as a class method to the created subclass
        cls.reset_singleton = classmethod(reset_singleton)

        return cls

    def __call__(mcs, cls, *args, **kwargs):
        # Enforce the singleton pattern: check if an instance already exists for this specific class
        if cls not in mcs._instances:
            # Instantiate the class using the default type.__call__ (triggers __new__ and __init__)
            mcs._instances[cls] = super().__call__(cls, *args, **kwargs)

        return mcs._instances[cls]

