class DynamicChain:
    def __init__(self, path=None):
        # Store the current chain of attributes as a list.
        # Initialize with an empty list if no path is provided.
        self._path = path if path is not None else []

    def __getattr__(self, name):
        # When an attribute is accessed that isn't explicitly defined,
        # create a new instance of DynamicChain containing the extended path.
        # Using a list addition (+) creates a new list, ensuring that
        # different chain branches do not interfere with each other.
        return DynamicChain(self._path + [name])

    def __call__(self):
        # When the resulting object is called, return the path joined by dots.
        return ".".join(self._path)

