def final(cls):
    """Decorator to mark a class as final, preventing subclassing."""
    cls.__final__ = True
    return cls

def abstractmethod(func):
    """Decorator to mark a method as abstract, preventing instantiation."""
    func.__abstract__ = True
    return func

class Enforcer(type):
    def __new__(mcs, name, bases, attrs):
        # Check if any of the parent classes are marked as final
        for base in bases:
            if getattr(base, '__final__', False):
                raise TypeError(f"Class {base.__name__} is decorated with @final and cannot be subclassed.")

        return super().__new__(mcs, name, bases, attrs)

    def __call__(cls, *args, **kwargs):
        # Check if the class or any of its parents contain an abstract method
        # dir() is used to inspect all attributes including those inherited from base classes
        for attr_name in dir(cls):
            attr = getattr(cls, attr_name)
            if getattr(attr, '__abstract__', False):
                raise TypeError(
                    f"Class {cls.__name__} cannot be instantiated because it contains "
                    f"abstract method '{attr_name}'."
                )

        return super().__call__(*args, **kwargs)

