import ast
import inspect
import textwrap

class SecurityError(Exception):
    """Custom exception raised when a global variable access is detected in a jailed class."""
    pass

class JailedMeta(type):
    def __new__(mcs, name, bases, attrs):
        for attr_name, attr_value in attrs.items():
            # We only analyze user-defined functions (methods) in the class
            if callable(attr_value) and hasattr(attr_value, '__code__'):
                try:
                    # Retrieve the source code of the method
                    source = inspect.getsource(attr_value)
                    # Dedent the source to ensure the AST parser can handle it
                    dedented_source = textwrap.dedent(source)
                    tree = ast.parse(dedented_source)
                except (OSError, TypeError, SyntaxError):
                    # If source cannot be retrieved or parsed, we skip the check for this method
                    continue

                # The parsed tree might contain the function definition inside other nodes
                func_node = None
                for node in ast.walk(tree):
                    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        func_node = node
                        break

                if func_node:
                    # Step 1: Collect all "safe" names (parameters and local assignments)
                    local_vars = set()

                    # Collect function arguments
                    all_args = func_node.args.args + func_node.args.kwonlyargs
                    for arg in all_args:
                        local_vars.add(arg.arg)
                    if func_node.args.vararg:
                        local_vars.add(func_node.args.vararg.arg)
                    if func_node.args.kwarg:
                        local_vars.add(func_node.args.kwarg.arg)

                    # Collect all variables that are assigned to within the function body
                    # This includes targets of assignments, for-loops, and with-statements
                    for node in ast.walk(func_node):
                        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
                            local_vars.add(node.id)

                    # Step 2: Check all variable loads against the safe set
                    for node in ast.walk(func_node):
                        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
                            # If the variable is loaded but was not defined as a local or parameter,
                            # it is considered a global/non-local variable.
                            if node.id not in local_vars:
                                raise SecurityError(f"Global variable access detected: {node.id}")

        return super().__new__(mcs, name, bases, attrs)

