class FlexNumber:
    def __init__(self, value, ops):
        """
        Initialize FlexNumber with a value and a dictionary of operator behaviors.
        :param value: The numeric value of the FlexNumber.
        :param ops: A dictionary mapping operator strings ('+', '-', '*') to functions.
        """
        self.value = value
        self.ops = ops

    def _get_operand_value(self, other):
        """Helper to extract the value if 'other' is a FlexNumber instance."""
        if isinstance(other, FlexNumber):
            return other.value
        return other

    def __add__(self, other):
        val_other = self._get_operand_value(other)
        # Use provided lambda for '+', default to standard addition
        op_func = self.ops.get('+', lambda x, y: x + y)
        result = op_func(self.value, val_other)
        return FlexNumber(result, self.ops)

    def __sub__(self, other):
        val_other = self._get_operand_value(other)
        # Use provided lambda for '-', default to standard subtraction
        op_func = self.ops.get('-', lambda x, y: x - y)
        result = op_func(self.value, val_other)
        return FlexNumber(result, self.ops)

    def __mul__(self, other):
        val_other = self._get_operand_value(other)
        # Use provided lambda for '*', default to standard multiplication
        op_func = self.ops.get('*', lambda x, y: x * y)
        result = op_func(self.value, val_other)
        return FlexNumber(result, self.ops)

    def __repr__(self):
        return f"FlexNumber({self.value})"

