import threading

class DeadlockPotentialError(Exception):
    """Exception raised when a lock acquisition would potentially create a deadlock."""
    pass

class DeadlockLock:
    # Global structures to track the lock dependency graph
    # _lock_owners: maps a lock instance to the thread ID currently holding it
    # _thread_waiting: maps a thread ID to the lock instance it is currently waiting for
    _lock_owners = {}
    _thread_waiting = {}
    _graph_lock = threading.Lock()

    def __init__(self):
        self._internal_lock = threading.Lock()

    def acquire(self, blocking=True, timeout=-1):
        me = threading.get_ident()

        with DeadlockLock._graph_lock:
            owner = DeadlockLock._lock_owners.get(self)

            if owner is not None:
                if owner == me:
                    # A thread attempting to acquire a non-recursive lock it already holds is a deadlock
                    raise DeadlockPotentialError("Potential deadlock detected: thread already owns lock")

                # Check for cycles in the dependency graph:
                # me -> self (lock) -> owner -> (whatever owner is waiting for) -> ...
                curr_thread = owner
                while curr_thread in DeadlockLock._thread_waiting:
                    waiting_for_lock = DeadlockLock._thread_waiting[curr_thread]
                    next_thread = DeadlockLock._lock_owners.get(waiting_for_lock)

                    if next_thread is None:
                        break
                    if next_thread == me:
                        raise DeadlockPotentialError("Potential deadlock detected: cycle in lock dependency graph")
                    curr_thread = next_thread

                # If no cycle is found and we are about to block, record that we are waiting for this lock
                if blocking:
                    DeadlockLock._thread_waiting[me] = self

        # Attempt to acquire the actual lock
        acquired = self._internal_lock.acquire(blocking=blocking, timeout=timeout)

        with DeadlockLock._graph_lock:
            if acquired:
                # Update ownership
                DeadlockLock._lock_owners[self] = me

            # Once we have acquired the lock (or stopped trying), we are no longer waiting
            if me in DeadlockLock._thread_waiting:
                del DeadlockLock._thread_waiting[me]

        return acquired

    def release(self):
        me = threading.get_ident()
        with DeadlockLock._graph_lock:
            if DeadlockLock._lock_owners.get(self) == me:
                del DeadlockLock._lock_owners[self]
            else:
                # To mirror threading.Lock behavior, we let the internal lock raise 
                # RuntimeError if the thread doesn't own it.
                pass
        self._internal_lock.release()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.release()

