async_retry_with_backoff.code:
import asyncio
import random
import functools

def async_retry(exceptions, max_retries, base_delay, backoff_factor, jitter):
    """
    Decorator for async functions to retry on specified exceptions with 
    exponential backoff and optional randomized jitter.
    """
    def decorator(func):
        @functools.wraps(func)
        async def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                try:
                    return await func(*args, **kwargs)
                except exceptions as e:
                    if attempt >= max_retries:
                        raise e

                    # Calculate exponential backoff
                    delay = base_delay * (backoff_factor ** attempt)

                    # Apply randomized jitter (+/- 10% of the current delay)
                    if jitter:
                        jitter_amount = delay * random.uniform(-0.1, 0.1)
                        delay += jitter_amount

                    await asyncio.sleep(delay)
                    attempt += 1
        return wrapper
    return decorator

