def parse_json(s: str):
    """
    Parses a JSON string into Python primitives without using the json library or eval/exec.
    """
    index = 0

    def skip_whitespace():
        nonlocal index
        while index < len(s) and s[index] in ' \n\r\t':
            index += 1

    def parse_value():
        skip_whitespace()
        if index >= len(s):
            raise ValueError("Unexpected end of input")

        char = s[index]

        if char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        elif char == '"':
            return parse_string()
        elif char == 't':
            return parse_constant('true', True)
        elif char == 'f':
            return parse_constant('false', False)
        elif char == 'n':
            return parse_constant('null', None)
        elif char == '-' or char.isdigit():
            return parse_number()
        else:
            raise ValueError(f"Unexpected character '{char}' at index {index}")

    def parse_string():
        nonlocal index
        index += 1  # Skip opening quote
        result = []
        while index < len(s):
            char = s[index]
            if char == '"':
                index += 1  # Skip closing quote
                return "".join(result)
            elif char == '\\':
                index += 1
                if index >= len(s):
                    raise ValueError("Unterminated escape sequence")
                esc = s[index]
                if esc == '"': result.append('"')
                elif esc == '\\': result.append('\\')
                elif esc == '/': result.append('/')
                elif esc == 'b': result.append('\b')
                elif esc == 'f': result.append('\f')
                elif esc == 'n': result.append('\n')
                elif esc == 'r': result.append('\r')
                elif esc == 't': result.append('\t')
                elif esc == 'u':
                    if index + 4 >= len(s):
                        raise ValueError("Invalid unicode escape")
                    hex_val = s[index + 1 : index + 5]
                    result.append(chr(int(hex_val, 16)))
                    index += 4
                else:
                    raise ValueError(f"Invalid escape character '{esc}'")
            else:
                result.append(char)
            index += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start = index
        if s[index] == '-':
            index += 1

        # Integer part
        while index < len(s) and s[index].isdigit():
            index += 1

        # Fractional part
        if index < len(s) and s[index] == '.':
            index += 1
            while index < len(s) and s[index].isdigit():
                index += 1

        # Exponent part
        if index < len(s) and s[index] in 'eE':
            index += 1
            if index < len(s) and s[index] in '+-':
                index += 1
            while index < len(s) and s[index].isdigit():
                index += 1

        num_str = s[start:index]
        if '.' in num_str or 'e' in num_str.lower():
            return float(num_str)
        return int(num_str)

    def parse_constant(expected, value):
        nonlocal index
        if s[index : index + len(expected)] == expected:
            index += len(expected)
            return value
        raise ValueError(f"Expected {expected} at index {index}")

    def parse_array():
        nonlocal index
        index += 1  # Skip [
        result = []
        skip_whitespace()
        if index < len(s) and s[index] == ']':
            index += 1
            return result

        while True:
