                index += 1
                skip_whitespace()
            elif index < len(s) and s[index] == ']':
                index += 1
                return result
            else:
                raise ValueError(f"Expected ',' or ']' in array at index {index}")

    def parse_object():
        nonlocal index
        index += 1  # Skip {
        result = {}
        skip_whitespace()
        if index < len(s) and s[index] == '}':
            index += 1
            return result

