from datetime import datetime, timedelta

def next_cron_run(cron_expr: str, start_time: datetime) -> datetime:
    """
    Parses a standard 5-field cron expression and returns the next execution 
    datetime strictly after start_time.
    """
    def parse_field(field, min_val, max_val):
        allowed = set()
        for part in field.split(','):
            if '/' in part:
                range_part, step_part = part.split('/')
                step = int(step_part)
                if range_part == '*':
                    start, end = min_val, max_val
                elif '-' in range_part:
                    start, end = map(int, range_part.split('-'))
                else:
                    start = end = int(range_part)
                for i in range(start, end + 1, step):
                    allowed.add(i)
            elif '-' in part:
                start, end = map(int, part.split('-'))
                for i in range(start, end + 1):
                    allowed.add(i)
            elif part == '*':
                for i in range(min_val, max_val + 1):
                    allowed.add(i)
            else:
                allowed.add(int(part))
        return allowed

    fields = cron_expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields.")

    minutes_set = parse_field(fields[0], 0, 59)
    hours_set = parse_field(fields[1], 0, 23)
    doms_set = parse_field(fields[2], 1, 31)
    months_set = parse_field(fields[3], 1, 12)
    # Cron 0=Sun, 1=Mon...6=Sat. Python weekday() 0=Mon, 6=Sun.
    # Convert Cron DOW to Python weekday values: (cron_dow - 1) % 7
    dows_set = {(d - 1) % 7 for d in parse_field(fields[4], 0, 6)}

    dom_expr = fields[2]
    dow_expr = fields[4]

    def is_valid_day(dt):
        dom_match = dt.day in doms_set
        dow_match = dt.weekday() in dows_set
        dom_restricted = dom_expr != '*'
        dow_restricted = dow_expr != '*'

        # Standard cron logic: if both DOM and DOW are restricted, 
        # the job runs when EITHER matches. Otherwise, it's an AND.
        if dom_restricted and dow_restricted:
            return dom_match or dow_match
        if dom_restricted:
            return dom_match
        if dow_restricted:
            return dow_match
        return True

    # Move to the start of the next potential minute strictly after start_time
    current = (start_time + timedelta(minutes=1)).replace(second=0, microsecond=0)
    # If start_time was not at the start of a minute, (start_time + 1min).replace(sec=0)
    # might actually be in the same minute as start_time. 
    # We must ensure the result is strictly after start_time.
    if current <= start_time:
        current += timedelta(minutes=1)

    while True:
        # Month check
        if current.month not in months_set:
            m = current.month
            while m not in months_set:
                m += 1
                if m > 12:
                    m = 1
            if m <= current.month:
                current = current.replace(year=current.year + 1, month=m, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=m, day=1, hour=0, minute=0)
            continue

        # Day check
        if not is_valid_day(current):
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Hour check
        if current.hour not in hours_set:
            # Find next valid hour in the same day
            h = current.hour
            found_hour = False
            while h < 24:
                h += 1
                if h in hours_set:
                    current = current.replace(hour=h, minute=0)
                    found_hour = True
                    break
            if not found_hour:
                current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Minute check
        if current.minute not in minutes_set:
            # Find next valid minute in the same hour
            m = current.minute
            found_min = False
            while m < 60:
                m += 1
                if m in minutes_set:
                    current = current.replace(minute=m)
                    found_min = True
                    break
            if not found_min:
                current = (current + timedelta(hours=1)).replace(minute=0)
            continue

        return current

