def match_pattern(pattern: str, text: str) -> bool:
    """
    Simplified regex matcher supporting simple characters, '.', '*', '?', and '+'.
    The matcher ensures the entire text is consumed.
    """
    # Pre-process the pattern into tokens of (character, quantifier)
    # Quantifiers: '1' (exactly one), '*' (zero or more), '?' (zero or one), '+' (one or more)
    tokens = []
    i = 0
    while i < len(pattern):
        char = pattern[i]
        if i + 1 < len(pattern) and pattern[i + 1] in '*?+':
            tokens.append((char, pattern[i + 1]))
            i += 2
        else:
            tokens.append((char, '1'))
            i += 1

    memo = {}

    def solve(t_idx, s_idx, is_star=False):
        """
        Recursive helper with memoization.
        t_idx: Current token index in the tokenized pattern.
        s_idx: Current character index in the text string.
        is_star: A flag indicating if the current token should be treated as a '*' quantifier.
        """
        state = (t_idx, s_idx, is_star)
        if state in memo:
            return memo[state]

        # Base case: If we have processed all tokens, the text must also be fully consumed.
        if t_idx == len(tokens):
            return s_idx == len(text)

        char, quant = tokens[t_idx]
        # If is_star is True, we override the original quantifier to '*'
        eff_quant = '*' if is_star else quant

        if eff_quant == '1':
            # Match exactly one character
            if s_idx < len(text) and (char == '.' or char == text[s_idx]):
                res = solve(t_idx + 1, s_idx + 1, False)
            else:
                res = False

        elif eff_quant == '*':
            # Case 1: Match zero occurrences (skip token)
            res = solve(t_idx + 1, s_idx, False)
            # Case 2: Match one or more occurrences
            if not res and s_idx < len(text) and (char == '.' or char == text[s_idx]):
                res = solve(t_idx, s_idx + 1, True)

        elif eff_quant == '?':
            # Case 1: Match zero occurrences (skip token)
            res = solve(t_idx + 1, s_idx, False)
            # Case 2: Match exactly one occurrence
            if not res and s_idx < len(text) and (char == '.' or char == text[s_idx]):
                res = solve(t_idx + 1, s_idx + 1, False)

        elif eff_quant == '+':
            # Must match at least one character
            if s_idx < len(text) and (char == '.' or char == text[s_idx]):
                # After matching the first character, it behaves like a '*' (zero or more)
                res = solve(t_idx, s_idx + 1, True)
            else:
                res = False
        else:
            res = False

        memo[state] = res
        return res

    return solve(0, 0, False)

