import re

def decode_html_entities(s: str) -> str:
    """
    Decodes HTML entities (decimal, hexadecimal, and specific named entities) 
    without using the html standard library.
    """
    # Mapping of common named entities as requested
    NAMED_ENTITIES = {
        'lt': '<',
        'gt': '>',
        'amp': '&',
        'quot': '"',
        'apos': "'"
    }

    def replace_entity(match):
        # Extract the content inside '&' and ';'
        entity = match.group(1)

        try:
            # Hexadecimal entities: &#x...; or &#X...;
            if entity.lower().startswith('#x'):
                return chr(int(entity[2:], 16))

            # Decimal entities: &#...;
            elif entity.startswith('#'):
                return chr(int(entity[1:]))

            # Named entities: &...;
            else:
                # Return the decoded character if it exists in our map, 
                # otherwise return the original match string
                return NAMED_ENTITIES.get(entity, match.group(0))
        except (ValueError, OverflowError):
            # In case the numeric value is invalid or outside Unicode range
            return match.group(0)

    # Regex pattern:
    # & matches the literal ampersand
    # ( ... ) capturing group for the entity content
    # #x[0-9a-fA-F]+  -> hex entities
    # #\d+            -> decimal entities
    # [a-zA-Z0-9]+    -> named entities
    # ; matches the literal semicolon
    pattern = r'&(#x[0-9a-fA-F]+|#\d+|[a-zA-Z0-9]+);'

    return re.sub(pattern, replace_entity, s, flags=re.IGNORECASE)

