import urllib.parse
import re

def parse_query_string(qs: str) -> dict:
    """
    Parses a query string into a dictionary, supporting percentage-decoded strings,
    duplicate keys (as lists), and nested objects via bracket syntax.
    """
    if not qs:
        return {}

    result = {}
    # Split the query string into key-value pairs
    pairs = qs.split('&')

    for pair in pairs:
        if not pair:
            continue

        # Split the pair into key and value
        if '=' in pair:
            raw_k, raw_v = pair.split('=', 1)
        else:
            raw_k, raw_v = pair, ''

        # Decode percentage-encoded strings
        k = urllib.parse.unquote(raw_k)
        v = urllib.parse.unquote(raw_v)

        # Parse brackets for nested structures
        # e.g., 'filters[price][lt]' -> path=['filters', 'price', 'lt']
        first_bracket = k.find('[')
        if first_bracket == -1:
            path = [k]
        else:
            root = k[:first_bracket]
            # Find all content inside square brackets
            brackets = re.findall(r'\[([^\]]*)\]', k[first_bracket:])
            path = [root] + brackets

        # Traverse the dictionary and create nested structures
        current = result
        for i in range(len(path) - 1):
            part = path[i]
            # If the key doesn't exist or is not a dictionary, initialize it as one
            if part not in current or not isinstance(current[part], dict):
                current[part] = {}
            current = current[part]

        # Handle the leaf node (the final key in the path)
        last_key = path[-1]
        if last_key in current:
            # If the key already exists, convert to/append to a list
            if isinstance(current[last_key], list):
                current[last_key].append(v)
            else:
                current[last_key] = [current[last_key], v]
        else:
            # First occurrence of the key
            current[last_key] = v

    return result

