class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class WildcardTrie:
    def __init__(self):
        """
        Initialize the WildcardTrie with a root node.
        """
        self.root = TrieNode()

    def insert(self, word: str):
        """
        Inserts a word into the trie.
        """
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def search(self, word: str) -> bool:
        """
        Returns True if the word is in the trie. 
        The character '.' can match any single character.
        """
        def dfs(node, index):
            # Base case: reached the end of the search word
            if index == len(word):
                return node.is_end

            char = word[index]

            if char == '.':
                # Wildcard: try every possible child node at this level
                for child in node.children.values():
                    if dfs(child, index + 1):
                        return True
                return False
            else:
                # Literal character: move to the specific child if it exists
                if char in node.children:
                    return dfs(node.children[char], index + 1)
                else:
                    return False

        return dfs(self.root, 0)

