        self.color = color  # "RED" or "BLACK"
        self.left = None
        self.right = None
        self.parent = None

class RedBlackTree:
    def __init__(self):
        # TNULL is the sentinel node used to represent leaf nodes (NIL)
        # All leaves in an RBT are black by definition.
        self.TNULL = Node(0, color="BLACK")
        self.root = self.TNULL

    def left_rotate(self, x):
        y = x.right
        x.right = y.left
        if y.left != self.TNULL:
            y.left.parent = x

        y.parent = x.parent
        if x.parent == None:
            self.root = y
        elif x == x.parent.left:
            x.parent.left = y
        else:
            x.parent.right = y
        y.left = x
        x.parent = y

    def right_rotate(self, x):
        y = x.left
        x.left = y.right
        if y.right != self.TNULL:
            y.right.parent = x

        y.parent = x.parent
        if x.parent == None:
            self.root = y
        elif x == x.parent.right:
            x.parent.right = y
        else:
            x.parent.left = y
        y.right = x
        x.parent = y

    def insert(self, val):
        # 1. Standard BST Insertion
        node = Node(val)
        node.parent = None
        node.left = self.TNULL
        node.right = self.TNULL
        node.color = "RED"

        y = None
        x = self.root

        while x != self.TNULL:
            y = x
            if node.val < x.val:
                x = x.left
            else:
                x = x.right

        node.parent = y
        if y == None:
            self.root = node
        elif node.val < y.val:
            y.left = node
        else:
            y.right = node

        # 2. Fix RBT properties
        if node.parent == None:
            node.color = "BLACK"
            return

        if node.parent.parent == None:
            return

        self._fix_insert(node)

    def _fix_insert(self, k):
        while k.parent.color == "RED":
            if k.parent == k.parent.parent.right:
                u = k.parent.parent.left # uncle
                if u.color == "RED":
                    # Case 1: Uncle is red -> Recolor
                    u.color = "BLACK"
                    k.parent.color = "BLACK"
                    k.parent.parent.color = "RED"
                    k = k.parent.parent
                else:
                    if k == k.parent.left:
                        # Case 2: Uncle is black, k is left child (Triangle)
                        k = k.parent
                        self.right_rotate(k)
                    # Case 3: Uncle is black, k is right child (Line)
                    k.parent.color = "BLACK"
                    k.parent.parent.color = "RED"
                    self.left_rotate(k.parent.parent)
            else:
                u = k.parent.parent.right # uncle
                if u.color == "RED":
                    # Case 1: Uncle is red -> Recolor
                    u.color = "BLACK"
                    k.parent.color = "BLACK"
                    k.parent.parent.color = "RED"
                    k = k.parent.parent
                else:
                    if k == k.parent.right:
                        # Case 2: Uncle is black, k is right child (Triangle)
                        k = k.parent
                        self.left_rotate(k)
                    # Case 3: Uncle is black, k is left child (Line)
                    k.parent.color = "BLACK"
                    k.parent.parent.color = "RED"
                    self.right_rotate(k.parent.parent)
            if k == self.root:
                break
        self.root.color = "BLACK"

    def is_valid_rbt(self) -> bool:
        if self.root == self.TNULL:
            return True

        # Property 1: Root must be black
        if self.root.color != "BLACK":
            return False

        # Properties 2 & 3: No red-red violations and constant black height
        # We use a recursive helper that returns the black height of the subtree
        # or -1 if a violation is found.
        def check_properties(node):
            if node == self.TNULL:
                return 1 # TNULL is black

            # Property 2: No red node has a red child
            if node.color == "RED":
                if node.left.color == "RED" or node.right.color == "RED":
                    return -1

            left_black_height = check_properties(node.left)
            right_black_height = check_properties(node.right)

            # If a violation was found in subtrees or black heights differ
            if left_black_height == -1 or right_black_height == -1:
                return -1
            if left_black_height != right_black_height:
                return -1

            # Return black height of current node
            return left_black_height + (1 if node.color == "BLACK" else 0)

        return check_properties(self.root) != -1

# Example Usage/Verification
