import heapq

def bidirectional_dijkstra(graph: dict, start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements a bidirectional Dijkstra's algorithm to find the shortest path in a weighted graph.

    Args:
        graph: A dictionary mapping node names to lists of tuples (neighbor_name, weight).
        start: The starting node name.
        end: The destination node name.

    Returns:
        A tuple containing the shortest path cost (float) and the path (list of node names).
    """
    # Handle case where start and end are the same
    if start == end:
        return 0.0, [start]

    # Collect all unique nodes present in the graph to initialize distance maps
    nodes = set(graph.keys())
    for neighbors in graph.values():
        for v, w in neighbors:
            nodes.add(v)

    # If start or end nodes are not in the graph, no path can exist
    if start not in nodes or end not in nodes:
        return float('inf'), []

    # Build a reverse graph to support backward search in directed graphs
    rev_graph = {node: [] for node in nodes}
    for u in graph:
        for v, w in graph[u]:
            rev_graph[v].append((u, w))

    # Initialization for forward search
    dist_f = {node: float('inf') for node in nodes}
    parent_f = {node: None for node in nodes}
    dist_f[start] = 0
    pq_f = [(0.0, start)]

    # Initialization for backward search
    dist_b = {node: float('inf') for node in nodes}
    parent_b = {node: None for node in nodes}
    dist_b[end] = 0
    pq_b = [(0.0, end)]

    # mu stores the current best shortest path distance found so far
    mu = float('inf')
    best_node = None

    while pq_f and pq_b:
        # Stopping condition: if the sum of the closest nodes in both priority queues
        # is greater than or equal to the best distance found, the shortest path is found.
        if pq_f[0][0] + pq_b[0][0] >= mu:
            break

        # Optimization: process the smaller priority queue to keep the search balanced
        if len(pq_f) <= len(pq_b):
            d, u = heapq.heappop(pq_f)
            if d > dist_f[u]:
                continue

            for v, w in graph.get(u, []):
                if dist_f[u] + w < dist_f[v]:
                    dist_f[v] = dist_f[u] + w
                    parent_f[v] = u
                    heapq.heappush(pq_f, (dist_f[v], v))
                    # Update mu if this node has also been visited by the backward search
                    if dist_b[v] != float('inf'):
                        if dist_f[v] + dist_b[v] < mu:
                            mu = dist_f[v] + dist_b[v]
                            best_node = v
        else:
            d, u = heapq.heappop(pq_b)
            if d > dist_b[u]:
                continue

            for v, w in rev_graph.get(u, []):
                if dist_b[u] + w < dist_b[v]:
                    dist_b[v] = dist_b[u] + w
                    parent_b[v] = u
                    heapq.heappush(pq_b, (dist_b[v], v))
                    # Update mu if this node has also been visited by the forward search
                    if dist_f[v] != float('inf'):
                        if dist_f[v] + dist_b[v] < mu:
                            mu = dist_f[v] + dist_b[v]
                            best_node = v

    # If no path was found
    if best_node is None:
        return float('inf'), []

    # Reconstruct the full path from start to end
    path = []

    # Forward part: backtrack from best_node to start
    curr = best_node
    while curr is not None:
        path.append(curr)
        curr = parent_f[curr]
    path.reverse()

    # Backward part: follow parents from best_node to end
    curr = parent_b[best_node]
    while curr is not None:
        path.append(curr)
        curr = parent_b[curr]

    return float(mu), path

