import struct

def float_to_bin32(f: float) -> str:
    """
    Converts a Python float (64-bit) to a 32-bit IEEE 754 binary string.
    The struct module is used to handle the conversion to single precision
    and the necessary rounding (round-to-nearest, ties-to-even).
    """
    # Pack the float as a 32-bit single precision float ('f')
    # '!' ensures network byte order (big-endian)
    try:
        packed = struct.pack('!f', f)
    except OverflowError:
        # Handle cases where the float is too large for 32-bit representation
        # by converting to infinity based on sign
        if f > 0:
            f = float('inf')
        else:
            f = float('-inf')
        packed = struct.pack('!f', f)

    # Unpack the packed bytes into an unsigned 32-bit integer ('I')
    integer_val = struct.unpack('!I', packed)[0]

    # Format as a 32-character binary string with leading zeros
    return f"{integer_val:032b}"

def bin32_to_float(b: str) -> float:
    """
    Converts a 32-bit IEEE 754 binary string back to a Python float.
    Handles normalized numbers, subnormals, infinity, and NaN.
    """
    if len(b) != 32:
        raise ValueError("Binary string must be exactly 32 characters long.")

    # Parse the string into the three IEEE 754 components
    sign_bit = int(b[0])
    exponent_bits = b[1:9]
    mantissa_bits = b[9:]

    E = int(exponent_bits, 2)
    M = int(mantissa_bits, 2)

    # Sign multiplier: (-1)^S
    sign = -1.0 if sign_bit == 1 else 1.0

    # Case 1: Special exponents (0 or 255)
    if E == 0:
        if M == 0:
            # Signed Zero
            return sign * 0.0
        else:
            # Subnormal (denormalized) numbers
            # Value = (-1)^S * (0.M) * 2^-126
            return sign * (M / (2**23)) * (2**-126)

    elif E == 255:
        if M == 0:
            # Positive or Negative Infinity
            return sign * float('inf')
        else:
            # Not a Number (NaN)
            return float('nan')

    else:
        # Case 2: Normalized numbers
        # Value = (-1)^S * (1.M) * 2^(E - 127)
        return sign * (1 + M / (2**23)) * (2**(E - 127))

