        raise ValueError("Binary string must be exactly 32 characters long.")

    # Parse the string into the three IEEE 754 components
    sign_bit = int(b[0])
    exponent_bits = b[1:9]
    mantissa_bits = b[9:]

    E = int(exponent_bits, 2)
    M = int(mantissa_bits, 2)

    # Sign multiplier: (-1)^S
    sign = -1.0 if sign_bit == 1 else 1.0

    # Case 1: Special exponents (0 or 255)
    if E == 0:
        if M == 0:
            # Signed Zero
            return sign * 0.0
        else:
            # Subnormal (denormalized) numbers
            # Value = (-1)^S * (0.M) * 2^-126
            return sign * (M / (2**23)) * (2**-126)

    elif E == 255:
        if M == 0:
            # Positive or Negative Infinity
            return sign * float('inf')
        else:
            # Not a Number (NaN)
            return float('nan')

    else:
        # Case 2: Normalized numbers
        # Value = (-1)^S * (1.M) * 2^(E - 127)
        return sign * (1 + M / (2**23)) * (2**(E - 127))
