        self.ref_to = []

def find_and_break_cycles(nodes: list[GNode]) -> int:
    """
    Identifies cycles of unreachable objects (nodes that cannot be reached 
    from any node outside the cycle) and breaks them by clearing their 
    reference links. Returns the total number of broken links.
    """
    if not nodes:
        return 0

    # Mapping nodes to unique integers for graph algorithms
    node_to_id = {node: i for i, node in enumerate(nodes)}
    id_to_node = {i: node for i, node in enumerate(nodes)}
    n = len(nodes)

    # Tarjan's SCC Algorithm variables
    dfn = [-1] * n
    low = [-1] * n
    stack = []
    on_stack = [False] * n
    timer = 0
    sccs = []

    def find_scc(u_id):
        nonlocal timer
        dfn[u_id] = low[u_id] = timer
        timer += 1
        stack.append(u_id)
        on_stack[u_id] = True

        u_node = id_to_node[u_id]
        for v_node in u_node.ref_to:
            if v_node not in node_to_id:
                continue  # Ignore references to nodes not in the provided list
            v_id = node_to_id[v_node]
            if dfn[v_id] == -1:
                find_scc(v_id)
                low[u_id] = min(low[u_id], low[v_id])
            elif on_stack[v_id]:
                low[u_id] = min(low[u_id], dfn[v_id])

        if low[u_id] == dfn[u_id]:
            component = []
            while True:
                node_id = stack.pop()
                on_stack[node_id] = False
                component.append(node_id)
                if node_id == u_id:
                    break
            sccs.append(component)

    # Step 1: Find all Strongly Connected Components
    for i in range(n):
        if dfn[i] == -1:
            find_scc(i)

    # Step 2: Determine which SCCs are sources in the condensation graph
    # An SCC is a source if no node inside it is referenced by a node outside it.
    node_to_scc = {}
    for scc_id, component in enumerate(sccs):
        for node_id in component:
            node_to_scc[node_id] = scc_id

    scc_has_incoming = [False] * len(sccs)
    for u_id in range(n):
        u_node = id_to_node[u_id]
        u_scc = node_to_scc[u_id]
        for v_node in u_node.ref_to:
            if v_node not in node_to_id:
                continue
            v_id = node_to_id[v_node]
            v_scc = node_to_scc[v_id]
            if u_scc != v_scc:
                scc_has_incoming[v_scc] = True

    # Step 3: Identify source SCCs that contain a cycle
    nodes_to_break = []
    for scc_id, component in enumerate(sccs):
        if not scc_has_incoming[scc_id]:
            # An SCC contains a cycle if it has > 1 node or a single node with a self-loop
            is_cycle = False
            if len(component) > 1:
                is_cycle = True
            elif len(component) == 1:
                u_id = component[0]
                u_node = id_to_node[u_id]
                if any(v_node == u_node for v_node in u_node.ref_to):
                    is_cycle = True

            if is_cycle:
                nodes_to_break.extend([id_to_node[node_id] for node_id in component])

    # Step 4: Break the cycles and count broken links
    total_broken_links = 0
    for node in nodes_to_break:
        total_broken_links += len(node.ref_to)
        node.ref_to = []

    return total_broken_links

