import importlib.util

class DynamicLoader:
    """Loader responsible for executing the dynamic module."""
    def exec_module(self, module):
        # Define a class dynamically within the module's namespace
        class DynamicClass:
            def greet(self) -> str:
                return module.__name__

        # Attach the class to the module
        module.DynamicClass = DynamicClass

class DynamicImportHook:
    """Import hook that intercepts modules starting with 'dynamic_'."""
    def find_spec(self, fullname, path, target=None):
        if fullname.startswith("dynamic_"):
            # Return a ModuleSpec that uses our custom DynamicLoader
            return importlib.util.spec_from_loader(fullname, DynamicLoader())
        # Return None to allow other hooks in sys.meta_path to handle the import
        return None

# Register the hook in sys.meta_path
sys.meta_path.append(DynamicImportHook())

