import weakref

class StrictType:
    """
    A descriptor that enforces type checking and optional validation at runtime.
    Uses a WeakKeyDictionary to prevent memory leaks by allowing instances 
    to be garbage collected even while stored in the descriptor.
    """
    def __init__(self, type_, validator=None):
        self.type_ = type_
        self.validator = validator
        # WeakKeyDictionary ensures that the 'instance' keys are weakly referenced,
        # preventing the descriptor from keeping the objects alive in memory.
        self._values = weakref.WeakKeyDictionary()

    def __get__(self, instance, owner):
        # Return the descriptor object itself if accessed through the class
        if instance is None:
            return self

        try:
            return self._values[instance]
        except KeyError:
            raise AttributeError(f"'{owner.__name__}' object has no attribute set for this descriptor.")

    def __set__(self, instance, value):
        # 1. Check if the value is of the correct type
        if not isinstance(value, self.type_):
            raise TypeError(f"Expected value of type {self.type_}, but got {type(value).__name__}")

        # 2. Check if the optional validator returns True
        if self.validator is not None:
            if not self.validator(value):
                raise ValueError(f"Value {value!r} failed the validation check.")

        # Store the validated value associated with the specific instance
        self._values[instance] = value

