class RegistrySingleton(type):
    _subclasses = {}
    _instances = {}

    def __new__(mcs, name, bases, attrs):
        # Create the class using the base type's __new__ method
        cls = super().__new__(mcs, name, bases, attrs)

        # Automatically register the subclass in the global directory
        # Using mcs._subclasses to ensure it refers to the metaclass's attribute
        mcs._subclasses[name] = cls

        # Define the reset_singleton function to be added as a class method
        def reset_singleton(cls_ref):
            if cls_ref in mcs._instances:
                del mcs._instances[cls_ref]

        # Attach the method as a classmethod to the created class
        cls.reset_singleton = classmethod(reset_singleton)

        return cls

    def __call__(cls, *args, **kwargs):
        # Enforce the singleton pattern by checking if an instance already exists for the class
        if cls not in RegistrySingleton._instances:
            # Instantiate the class if no instance is found
            instance = super().__call__(*args, **kwargs)
            RegistrySingleton._instances[cls] = instance

        return RegistrySingleton._instances[cls]

