class DynamicChain:
    def __init__(self, path=None):
        # Initialize with an empty list if no path is provided
        # This stores the sequence of attributes accessed
        self._path = path if path is not None else []

    def __getattr__(self, name):
        # When an attribute is accessed that isn't explicitly defined,
        # create a new instance of DynamicChain with the updated path.
        # We create a new list to ensure that different branches of a chain 
        # do not interfere with each other (immutability).
        new_path = self._path + [name]
        return DynamicChain(new_path)

    def __call__(self):
        # When the final object in the chain is called, 
        # return the attributes joined by dots.
        return ".".join(self._path)

