        # Prevent subclassing if any base class is decorated with @final
        for base in bases:
            if getattr(base, '_is_final', False):
                raise TypeError(f"Class {base.__name__} is final and cannot be subclassed")

        return super().__new__(mcs, name, bases, attrs)

    def __call__(cls, *args, **kwargs):
        # Prevent instantiation if the class contains any method decorated with @abstractmethod
        # We use dir() to check all attributes, including inherited ones,
        # to ensure a subclass has implemented all inherited abstract methods.
        for attr_name in dir(cls):
            attr = getattr(cls, attr_name)
            if getattr(attr, '_is_abstract', False):
                raise TypeError(f"Class {cls.__name__} cannot be instantiated because it has abstract methods")

        return super().__call__(*args, **kwargs)

