import dis
import types

class SecurityError(Exception):
    """Custom exception raised when a method attempts to access global variables."""
    pass

class JailedMeta(type):
    """
    Metaclass that inspects methods of a class to ensure they do not access 
    global variables or built-ins, allowing only local variables, parameters, 
    and attributes of 'self'.
    """
    def __new__(mcs, name, bases, attrs):
        for attr_name, attr_value in attrs.items():
            # Extract the underlying function if it's wrapped in staticmethod or classmethod
            func = attr_value
            if isinstance(attr_value, (staticmethod, classmethod)):
                func = attr_value.__func__

            # We only analyze callable objects that are functions (including lambdas)
            if isinstance(func, (types.FunctionType, types.MethodType)):
                # dis.get_instructions provides a sequence of bytecode instructions.
                # In Python, access to any variable not found in the local scope 
                # (locals, parameters) is performed via the LOAD_GLOBAL opcode.
                # This includes both module-level globals and Python built-ins.
                for instr in dis.get_instructions(func):
                    if instr.opname == 'LOAD_GLOBAL':
                        raise SecurityError(
                            f"Method '{attr_name}' is forbidden from accessing global variables or built-ins."
                        )

        return super().__new__(mcs, name, bases, attrs)

