class FlexNumber:
    """
    A class that allows dynamic overloading of arithmetic operators
    based on a behavior dictionary provided at construction time.
    """
    def __init__(self, value, ops):
        self.value = value
        self.ops = ops

    def _apply_op(self, op_symbol, other):
        # Extract the raw value if the other operand is also a FlexNumber
        other_val = other.value if isinstance(other, FlexNumber) else other

        # Retrieve the behavior function from the ops dictionary.
        # If the operator is not defined in the dictionary, default to the standard operation.
        op_func = self.ops.get(op_symbol)

        if op_func is None:
            if op_symbol == '+':
                op_func = lambda x, y: x + y
            elif op_symbol == '-':
                op_func = lambda x, y: x - y
            elif op_symbol == '*':
                op_func = lambda x, y: x * y
            else:
                raise NotImplementedError(f"Operator {op_symbol} is not supported.")

        # Calculate result and return a new FlexNumber instance to allow chaining
        result = op_func(self.value, other_val)
        return FlexNumber(result, self.ops)

    def __add__(self, other):
        return self._apply_op('+', other)

    def __sub__(self, other):
        return self._apply_op('-', other)

    def __mul__(self, other):
        return self._apply_op('*', other)

    def __repr__(self):
        return f"FlexNumber({self.value})"

    def __str__(self):
        return str(self.value)

