import threading

class DeadlockPotentialError(Exception):
    """Exception raised when a lock acquisition would potentially cause a deadlock."""
    pass

class DeadlockLock:
    # Global state to track lock dependencies across all DeadlockLock instances
    _global_state_lock = threading.Lock()
    _lock_owners = {}          # Maps lock instance -> thread identifier
    _dependencies = {}         # Maps lock A -> set of locks B (where a thread holds A and wants B)
    _thread_held_locks = {}    # Maps thread identifier -> set of lock instances held by that thread

    def __init__(self):
        self._internal_lock = threading.Lock()

    def _has_path(self, start_node, target_node):
        """Helper to detect if a path exists between two locks in the dependency graph."""
        if start_node == target_node:
            return True

        visited = set()
        stack = [start_node]
        while stack:
            curr = stack.pop()
            if curr == target_node:
                return True
            if curr not in visited:
                visited.add(curr)
                # Add all locks that are being waited for by threads holding 'curr'
                stack.extend(self._dependencies.get(curr, set()))
        return False

    def acquire(self, blocking=True, timeout=-1):
        tid = threading.get_ident()

        with self._global_state_lock:
            held_locks = self._thread_held_locks.get(tid, set())

            # Check if acquiring this lock creates a cycle
            # A cycle exists if the requested lock 'self' has a path back to any lock currently held
            for lock_held in held_locks:
                if self._has_path(self, lock_held):
                    raise DeadlockPotentialError("Potential deadlock detected: acquiring this lock would create a cycle in the dependency graph.")

            # Record that the thread holding these locks is now waiting for 'self'
            for lock_held in held_locks:
                self._dependencies.setdefault(lock_held, set()).add(self)

        try:
            # Attempt to acquire the actual threading.Lock
            acquired = self._internal_lock.acquire(blocking=blocking, timeout=timeout)
        finally:
            with self._global_state_lock:
                # Remove the temporary "waiting for" edges regardless of whether acquire succeeded
                held_locks = self._thread_held_locks.get(tid, set())
                for lock_held in held_locks:
                    if lock_held in self._dependencies and self in self._dependencies[lock_held]:
                        self._dependencies[lock_held].remove(self)

                # If lock was successfully acquired, update ownership records
                if acquired:
                    self._lock_owners[self] = tid
                    self._thread_held_locks.setdefault(tid, set()).add(self)

        return acquired

    def release(self):
        tid = threading.get_ident()

        with self._global_state_lock:
            # Remove ownership records
            if self._lock_owners.get(self) == tid:
                del self._lock_owners[self]
                if tid in self._thread_held_locks:
                    self._thread_held_locks[tid].discard(self)
            else:
                # Mirroring standard threading.Lock behavior: raise RuntimeError if releasing an unowned lock
                self._internal_lock.release() 
                # The line above will raise RuntimeError if not owned; we just let it propagate.
                return

        self._internal_lock.release()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.release()

