def parse_json(s: str) -> dict:
    """
    Parses a JSON string into Python primitives without using the json library, eval, or exec.
    """
    index = 0

    def skip_whitespace():
        nonlocal index
        while index < len(s) and s[index] in ' \n\r\t':
            index += 1

    def parse_value():
        skip_whitespace()
        if index >= len(s):
            raise ValueError("Unexpected end of input")

        char = s[index]

        if char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        elif char == '"':
            return parse_string()
        elif char == 't':
            return parse_literal('true', True)
        elif char == 'f':
            return parse_literal('false', False)
        elif char == 'n':
            return parse_literal('null', None)
        elif char == '-' or char.isdigit():
            return parse_number()
        else:
            raise ValueError(f"Unexpected character '{char}' at index {index}")

    def parse_string():
        nonlocal index
        index += 1  # Skip opening quote
        result = []

        escape_map = {
            'n': '\n',
            'r': '\r',
            't': '\t',
            'b': '\b',
            'f': '\f',
            '"': '"',
            '\\': '\\',
            '/': '/'
        }

        while index < len(s):
            char = s[index]
            if char == '"':
                index += 1  # Skip closing quote
                return "".join(result)
            elif char == '\\':
                index += 1
                if index >= len(s):
                    raise ValueError("Unterminated escape sequence")
                esc = s[index]
                if esc == 'u':
                    # Handle unicode \uXXXX
                    index += 1
                    hex_val = s[index:index+4]
                    if len(hex_val) < 4:
                        raise ValueError("Invalid unicode escape")
                    result.append(chr(int(hex_val, 16)))
                    index += 4
                elif esc in escape_map:
                    result.append(escape_map[esc])
                    index += 1
                else:
                    raise ValueError(f"Invalid escape sequence \\{esc}")
            else:
                result.append(char)
                index += 1

        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start = index
        if s[index] == '-':
            index += 1

        # Integer part
        while index < len(s) and s[index].isdigit():
            index += 1

        # Fractional part
        if index < len(s) and s[index] == '.':
            index += 1
            while index < len(s) and s[index].isdigit():
                index += 1

        # Exponent part
        if index < len(s) and s[index] in 'eE':
            index += 1
            if index < len(s) and s[index] in '+-':
                index += 1
            while index < len(s) and s[index].isdigit():
                index += 1

        num_str = s[start:index]
        if '.' in num_str or 'e' in num_str.lower():
            return float(num_str)
        return int(num_str)

    def parse_literal(literal, value):
        nonlocal index
        if s[index:index + len(literal)] == literal:
            index += len(literal)
            return value
        raise ValueError(f"Expected {literal} at index {index}")

    def parse_array():
        nonlocal index
        index += 1  # Skip [
        result = []
        skip_whitespace()

        if index < len(s) and s[index] == ']':
            index += 1
            return result

        while True:
            result.append(parse_value())
            skip_whitespace()
            if index < len(s) and s[index] == ']':
                index += 1
                return result
            if index >= len(s) or s[index] != ',':
                raise ValueError("Expected ',' or ']' in array")
            index += 1  # Skip comma
            skip_whitespace()

    def parse_object():
        nonlocal index
        index += 1  # Skip {
        result = {}
        skip_whitespace()

        if index < len(s) and s[index] == '}':
            index += 1
            return result

        while True:
            skip_whitespace()
            if index >= len(s) or s[index] != '"':
                raise ValueError("Expected string key in object")

            key = parse_string()
            skip_whitespace()

            if index >= len(s) or s[index] != ':':
                raise ValueError("Expected ':' after key in object")
            index += 1  # Skip :

            value = parse_value()
            result[key] = value

            skip_whitespace()
            if index < len(s) and s[index] == '}':
                index += 1
                return result
            if index >= len(s) or s[index] != ',':
                raise ValueError("Expected ',' or '}' in object")
            index += 1  # Skip comma

    # The JSON root must be a value (usually an object or array)
    final_result = parse_value()
    skip_whitespace()
    if index < len(s):
        raise ValueError("Trailing data after JSON value")

    return final_result

