import re

def decode_html_entities(s: str) -> str:
    """
    Decodes HTML entities in a string, supporting common named entities,
    decimal numeric entities, and hexadecimal numeric entities.
    """
    # Map of common named HTML entities to their corresponding characters
    named_entities = {
        "lt": "<",
        "gt": ">",
        "amp": "&",
        "quot": '"',
        "apos": "'"
    }

    def replace_entity(match):
        # entity is the content between '&' and ';'
        entity = match.group(1)

        # Hexadecimal entities: &#x...; or &#X...;
        if entity.startswith("#x") or entity.startswith("#X"):
            try:
                return chr(int(entity[2:], 16))
            except (ValueError, OverflowError):
                return match.group(0)

        # Decimal entities: &#...;
        elif entity.startswith("#"):
            try:
                return chr(int(entity[1:], 10))
            except (ValueError, OverflowError):
                return match.group(0)

        # Named entities: &...;
        else:
            # Return the decoded character if found, otherwise return the original match
            return named_entities.get(entity, match.group(0))

    # Regex pattern to find HTML entities:
    # & followed by (decimal #digit+, hex #xhex+, or alphanumeric named entities) followed by ;
    pattern = r"&(#x[0-9a-fA-F]+|#[0-9]+|[a-zA-Z0-9]+);"

    return re.sub(pattern, replace_entity, s)

