import urllib.parse
import re

def parse_query_string(qs: str) -> dict:
    """
    Parses a query string into a dictionary.
    Handles percentage-decoding, duplicate keys as lists, and nested objects via bracket syntax.
    """
    if not qs:
        return {}

    result = {}
    # Split the query string into key-value pairs
    pairs = qs.split('&')

    for pair in pairs:
        if not pair:
            continue

        # Split into key and value (handle keys without values)
        if '=' in pair:
            k_raw, v_raw = pair.split('=', 1)
        else:
            k_raw, v_raw = pair, ''

        # Decode percentage-encoded characters
        key = urllib.parse.unquote(k_raw)
        val = urllib.parse.unquote(v_raw)

        # Extract bracketed components (e.g., "filters[price][lt]" -> ["filters", "price", "lt"])
        # This regex matches any character that is not [ or ]
        keys = re.findall(r'([^\[\]]+)', key)

        if not keys:
            continue

        # Traverse the nested dictionary structure
        current = result
        for i in range(len(keys) - 1):
            k = keys[i]
            # If the key doesn't exist or isn't a dict, initialize it as a dict
            # to allow for nesting, even if a scalar value was previously assigned.
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]

        # Handle the leaf node (the final key in the bracket chain)
        last_key = keys[-1]
        if last_key in current:
            existing = current[last_key]
            if isinstance(existing, list):
                # Append to existing list
                existing.append(val)
            else:
                # Convert scalar to list to accommodate duplicate keys
                current[last_key] = [existing, val]
        else:
            # Assign value directly if it's the first time seeing this key
            current[last_key] = val

    return result

