import heapq

def bidirectional_dijkstra(graph: dict, start: str, end: str) -> tuple[float, list[str]]:
    """
    Finds the shortest path between start and end nodes in a weighted graph 
    using a bidirectional Dijkstra's algorithm.
    """
    if start == end:
        return (0.0, [start])

    # Build a reverse graph to allow searching backward from the end node
    rev_graph = {}
    for u in graph:
        for v, w in graph[u]:
            if v not in rev_graph:
                rev_graph[v] = []
            rev_graph[v].append((u, w))

    # Priority queues for forward and backward searches
    pq_f = [(0.0, start)]
    pq_b = [(0.0, end)]

    # Distance maps: node -> current shortest distance from start/end
    dist_f = {start: 0.0}
    dist_b = {end: 0.0}

    # Parent maps to reconstruct the path
    parent_f = {start: None}
    parent_b = {end: None}

    # Sets to keep track of settled nodes
    visited_f = set()
    visited_b = set()

    # mu stores the shortest path distance found so far
    mu = float('inf')
    # best_u and best_v store the meeting edge (best_u -> best_v)
    best_u = None
    best_v = None

    while pq_f and pq_b:
        # Termination condition: if the sum of the minimum distances in the two 
        # frontiers is already greater than or equal to the best path found, we can stop.
        if pq_f[0][0] + pq_b[0][0] >= mu:
            break

        # Expand the frontier that has the smaller minimum distance for efficiency
        if pq_f[0][0] <= pq_b[0][0]:
            d_u, u = heapq.heappop(pq_f)
            if u not in visited_f:
                visited_f.add(u)
                # Relax edges from the forward frontier
                for v, w in graph.get(u, []):
                    if dist_f.get(v, float('inf')) > dist_f[u] + w:
                        dist_f[v] = dist_f[u] + w
                        parent_f[v] = u
                        heapq.heappush(pq_f, (dist_f[v], v))
                    # If the neighbor is already visited by the backward search, 
                    # check if this edge provides a shorter overall path.
                    if v in visited_b:
                        if dist_f[u] + w + dist_b[v] < mu:
                            mu = dist_f[u] + w + dist_b[v]
                            best_u = u
                            best_v = v
        else:
            d_v, v = heapq.heappop(pq_b)
            if v not in visited_b:
                visited_b.add(v)
                # Relax edges from the backward frontier using the reversed graph
                for u, w in rev_graph.get(v, []):
                    if dist_b.get(u, float('inf')) > dist_b[v] + w:
                        dist_b[u] = dist_b[v] + w
                        parent_b[u] = v
                        heapq.heappush(pq_b, (dist_b[u], u))
                    # If the neighbor is already visited by the forward search, 
                    # check if this edge provides a shorter overall path.
                    if u in visited_f:
                        if dist_b[v] + w + dist_f[u] < mu:
                            mu = dist_b[v] + w + dist_f[u]
                            best_u = u
                            best_v = v

    # If mu remains infinity, no path exists between start and end
    if mu == float('inf'):
        return (float('inf'), [])

    # Path reconstruction: combine the path from start to best_u and best_v to end
    path = []
    curr = best_u
    while curr is not None:
        path.append(curr)
        curr = parent_f[curr]
    path.reverse()

    curr = best_v
    while curr is not None:
        path.append(curr)
        curr = parent_b[curr]

    return (float(mu), path)

