class ExactFraction:
    """
    A custom rational number class that represents a fraction and 
    automatically reduces it to its lowest terms.
    """

    def __init__(self, numerator, denominator):
        if denominator == 0:
            raise ZeroDivisionError("Denominator cannot be zero.")

        # Ensure inputs are integers
        self.num = int(numerator)
        self.den = int(denominator)
        self._simplify()

    def _simplify(self):
        """Reduces the fraction to its lowest terms and ensures the denominator is positive."""
        def get_gcd(a, b):
            while b:
                a, b = b, a % b
            return abs(a)

        common = get_gcd(self.num, self.den)
        self.num //= common
        self.den //= common

        # Ensure the sign is always carried by the numerator
        if self.den < 0:
            self.num = -self.num
            self.den = -self.den

    def _ensure_fraction(self, other):
        """Helper to convert integers to ExactFraction for mixed-type arithmetic."""
        if isinstance(other, int):
            return ExactFraction(other, 1)
        if isinstance(other, ExactFraction):
            return other
        raise TypeError("Unsupported operand type. Expected int or ExactFraction.")

    def __add__(self, other):
        other = self._ensure_fraction(other)
        # a/b + c/d = (ad + bc) / bd
        new_num = self.num * other.den + other.num * self.den
        new_den = self.den * other.den
        return ExactFraction(new_num, new_den)

    def __sub__(self, other):
        other = self._ensure_fraction(other)
        # a/b - c/d = (ad - bc) / bd
        new_num = self.num * other.den - other.num * self.den
        new_den = self.den * other.den
        return ExactFraction(new_num, new_den)

    def __mul__(self, other):
        other = self._ensure_fraction(other)
        # a/b * c/d = (ac) / (bd)
        new_num = self.num * other.num
        new_den = self.den * other.den
        return ExactFraction(new_num, new_den)

    def __truediv__(self, other):
        other = self._ensure_fraction(other)
        # a/b / c/d = (ad) / (bc)
        new_num = self.num * other.den
        new_den = self.den * other.num
        # The __init__ method will handle the ZeroDivisionError if new_den is 0
        return ExactFraction(new_num, new_den)

    def __eq__(self, other):
        if not isinstance(other, (int, ExactFraction)):
            return False
        other = self._ensure_fraction(other)
        return self.num == other.num and self.den == other.den

    def __str__(self):
        return f"{self.num}/{self.den}"

    def __repr__(self):
        return f"ExactFraction({self.num}, {self.den})"

