class GNode:
    """A dummy node representing an object in a memory heap."""
    def __init__(self):
        # List of references to other GNode objects
        self.ref_to = []

def find_and_break_cycles(nodes: list[GNode]) -> int:
    """
    Identifies cycles of unreachable objects (nodes that cannot be reached 
    from any node outside their own strongly connected component) and 
    breaks them by clearing their reference links.
    """
    if not nodes:
        return 0

    # Tarjan's Algorithm variables for finding Strongly Connected Components (SCCs)
    dfn = {}  # Discovery time
    low = {}  # Lowest discovery time reachable
    stack = []
    on_stack = set()
    sccs = []
    timer = 0

    def strongconnect(u):
        nonlocal timer
        dfn[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack.add(u)

        for v in u.ref_to:
            if v not in dfn:
                strongconnect(v)
                low[u] = min(low[u], low[v])
            elif v in on_stack:
                low[u] = min(low[u], dfn[v])

        # If u is a root node, pop the stack and generate an SCC
        if low[u] == dfn[u]:
            scc = []
            while True:
                w = stack.pop()
                on_stack.remove(w)
                scc.append(w)
                if w == u:
                    break
            sccs.append(scc)

    # Execute Tarjan's for all nodes in the input list
    for node in nodes:
        if node not in dfn:
            strongconnect(node)

    # Map each node to its corresponding SCC index for quick lookup
    node_to_scc = {}
    for i, scc in enumerate(sccs):
        for node in scc:
            node_to_scc[node] = i

    # An SCC is "reachable from outside" if any node within it has an 
    # incoming edge from a node that is not part of that same SCC.
    is_reachable_from_outside = [False] * len(sccs)
    for u in nodes:
        for v in u.ref_to:
            # Only consider references within the provided universe of nodes
            if v in node_to_scc:
                u_scc = node_to_scc[u]
                v_scc = node_to_scc[v]
                if u_scc != v_scc:
                    is_reachable_from_outside[v_scc] = True

    broken_links_count = 0
    garbage_nodes = set()

    # Identify SCCs that are cycles and are unreachable from outside
    for i, scc in enumerate(sccs):
        # A component is a cycle if it contains more than one node 
        # or if it contains a single node with a self-loop.
        is_cycle = False
        if len(scc) > 1:
            is_cycle = True
        elif len(scc) == 1:
            node = scc[0]
            if node in node.ref_to:
                is_cycle = True

        # If the component is a cycle and no one from outside points to it, it is garbage.
        if is_cycle and not is_reachable_from_outside[i]:
            for node in scc:
                garbage_nodes.add(node)

    # Break the links of all identified garbage nodes and count the edges removed
    for node in garbage_nodes:
        broken_links_count += len(node.ref_to)
        node.ref_to = []

    return broken_links_count

