import sys

def deep_size_of(obj, seen=None) -> int:
    """
    Recursively estimates the total memory footprint of a Python object.
    Handles circular references by keeping track of visited object IDs.
    """
    if seen is None:
        seen = set()

    obj_id = id(obj)
    if obj_id in seen:
        return 0

    # Mark this object as visited
    seen.add(obj_id)
    size = sys.getsizeof(obj)

    # Handle dictionaries: iterate over keys and values
    if isinstance(obj, dict):
        for k, v in obj.items():
            size += deep_size_of(k, seen)
            size += deep_size_of(v, seen)

    # Handle iterables: list, tuple, set, frozenset, deque, etc.
    elif isinstance(obj, (list, tuple, set, frozenset)):
        for item in obj:
            size += deep_size_of(item, seen)

    # Handle custom objects with __dict__ or __slots__
    else:
        # Check for __dict__ (standard object attributes)
        if hasattr(obj, '__dict__'):
            size += deep_size_of(vars(obj), seen)

        # Check for __slots__ (memory-optimized object attributes)
        if hasattr(obj, '__slots__'):
            slots = obj.__slots__
            # __slots__ can be a single string or an iterable of strings
            if isinstance(slots, str):
                slots = [slots]
            for slot in slots:
                try:
                    # Only add size if the slot is actually assigned a value
                    attr_value = getattr(obj, slot)
                    size += deep_size_of(attr_value, seen)
                except AttributeError:
                    continue

    return size

