import weakref

class StrictType:
    def __init__(self, expected_type, validator=None):
        self.expected_type = expected_type
        self.validator = validator
        # Use WeakKeyDictionary to prevent memory leaks by allowing 
        # instances to be garbage collected even if they are keys here.
        self._values = weakref.WeakKeyDictionary()

    def __get__(self, instance, owner):
        if instance is None:
            return self
        try:
            return self._values[instance]
        except KeyError:
            raise AttributeError(f"'{owner.__name__}' object has no attribute")

    def __set__(self, instance, value):
        # 1. Runtime type check
        if not isinstance(value, self.expected_type):
            raise TypeError(
                f"Expected {self.expected_type.__name__}, "
                f"got {type(value).__name__} instead."
            )

        # 2. Optional validator check
        if self.validator is not None:
            if not self.validator(value):
                raise ValueError(f"Value {value!r} failed validation.")

        # Store value associated with the specific instance
        self._values[instance] = value

