def final(cls):
    """Decorator to mark a class as final, preventing it from being subclassed."""
    cls._is_final = True
    return cls

def abstractmethod(func):
    """Decorator to mark a method as abstract, preventing instantiation of the class."""
    func._is_abstract = True
    return func

class Enforcer(type):
    """Metaclass that enforces finality and abstract method constraints."""

    def __new__(mcs, name, bases, attrs):
        # Check if any of the base classes are marked as @final
        for base in bases:
            if getattr(base, '_is_final', False):
                raise TypeError(f"Class {base.__name__} is final and cannot be subclassed.")

        return super().__new__(mcs, name, bases, attrs)

    def __call__(cls, *args, **kwargs):
        # Check if the class or any of its parents have an un-overridden @abstractmethod
        # dir(cls) looks up the inheritance chain for all attributes
        for attr_name in dir(cls):
            attr = getattr(cls, attr_name)
            if getattr(attr, '_is_abstract', False):
                raise TypeError(
                    f"Class {cls.__name__} cannot be instantiated because it contains "
                    f"an abstract method '{attr_name}'."
                )

        return super().__call__(*args, **kwargs)

