class FlexNumber:
    """
    A class that allows dynamic overloading of basic arithmetic operators (+, -, *)
    based on a dictionary of behavior functions provided at initialization.
    """
    def __init__(self, value, ops):
        self.value = value
        self.ops = ops

    def _get_operand_value(self, other):
        """Helper to extract value if the operand is another FlexNumber instance."""
        return other.value if isinstance(other, FlexNumber) else other

    def __add__(self, other):
        # Retrieve the function for '+' or default to standard addition
        operation = self.ops.get('+', lambda x, y: x + y)
        return operation(self.value, self._get_operand_value(other))

    def __sub__(self, other):
        # Retrieve the function for '-' or default to standard subtraction
        operation = self.ops.get('-', lambda x, y: x - y)
        return operation(self.value, self._get_operand_value(other))

    def __mul__(self, other):
        # Retrieve the function for '*' or default to standard multiplication
        operation = self.ops.get('*', lambda x, y: x * y)
        return operation(self.value, self._get_operand_value(other))

    def __repr__(self):
        return f"FlexNumber({self.value})"

