from datetime import datetime, timedelta

def next_cron_run(cron_expr: str, start_time: datetime) -> datetime:
    """
    Calculates the next execution datetime for a given 5-field cron expression
    strictly after the provided start_time.
    """

    def parse_field(expr, min_val, max_val):
        """Parses a cron field expression into a set of allowed integers."""
        vals = set()
        for part in expr.split(','):
            if '/' in part:
                range_part, step_str = part.split('/')
                step = int(step_str)
                if range_part == '*':
                    start, end = min_val, max_val
                elif '-' in range_part:
                    start, end = map(int, range_part.split('-'))
                else:
                    start, end = int(range_part), max_val
                for v in range(start, end + 1, step):
                    vals.add(v)
            elif '-' in part:
                start, end = map(int, part.split('-'))
                for v in range(start, end + 1):
                    vals.add(v)
            elif part == '*':
                for v in range(min_val, max_val + 1):
                    vals.add(v)
            else:
                vals.add(int(part))
        return vals

    # Parse the 5 fields of the cron expression
    fields = cron_expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields.")

    min_expr, hour_expr, dom_expr, month_expr, dow_expr = fields

    minutes = parse_field(min_expr, 0, 59)
    hours = parse_field(hour_expr, 0, 23)
    doms = parse_field(dom_expr, 1, 31)
    months = parse_field(month_expr, 1, 12)
    dows = parse_field(dow_expr, 0, 6)

    # Start searching strictly after start_time
    # We normalize to the start of the next minute
    dt = start_time + timedelta(minutes=1)
    dt = dt.replace(second=0, microsecond=0)

    while True:
        # 1. Check Month
        if dt.month not in months:
            found_month = False
            for m in range(dt.month + 1, 13):
                if m in months:
                    dt = dt.replace(month=m, day=1, hour=0, minute=0)
                    found_month = True
                    break
            if not found_month:
                # Move to the first valid month of the next year
                dt = dt.replace(year=dt.year + 1, month=1, day=1, hour=0, minute=0)
            continue

        # 2. Check Day (Day of Month and Day of Week)
        # Standard Cron Logic: If both DOM and DOW are restricted (not '*'),
        # the condition is an OR. Otherwise, it is an AND.
        is_dom_match = dt.day in doms
        # Python weekday: 0=Mon, 6=Sun. Cron: 0=Sun, 1=Mon, ..., 6=Sat.
        cron_dow = (dt.weekday() + 1) % 7
        is_dow_match = cron_dow in dows

        if dom_expr != '*' and dow_expr != '*':
            day_match = is_dom_match or is_dow_match
        else:
            day_match = is_dom_match and is_dow_match

        if not day_match:
            dt = dt + timedelta(days=1)
            dt = dt.replace(hour=0, minute=0)
            continue

        # 3. Check Hour
        if dt.hour not in hours:
            found_hour = False
            for h in range(dt.hour + 1, 24):
                if h in hours:
                    dt = dt.replace(hour=h, minute=0)
                    found_hour = True
                    break
            if not found_hour:
                dt = dt + timedelta(days=1)
                dt = dt.replace(hour=0, minute=0)
            continue

        # 4. Check Minute
        if dt.minute not in minutes:
            found_minute = False
            for m in range(dt.minute + 1, 60):
                if m in minutes:
                    dt = dt.replace(minute=m)
                    found_minute = True
                    break
            if not found_minute:
                dt = dt + timedelta(hours=1)
                dt = dt.replace(minute=0)
            continue

        # If we reach here, all fields match
        return dt

