import re

def decode_html_entities(s: str) -> str:
    """
    Decodes HTML entities in a string including decimal, hexadecimal, 
    and common named entities without using the html library.
    """
    # Mapping of common named entities to their character equivalents
    named_entities = {
        'lt': '<',
        'gt': '>',
        'amp': '&',
        'quot': '"',
        'apos': "'"
    }

    def replace_entity(match):
        # entity is the content between '&' and ';'
        entity = match.group(1)

        # Check for hexadecimal entities (&#x...; or &#X...;)
        if entity.startswith('#x') or entity.startswith('#X'):
            try:
                # Extract hex value and convert to integer, then to character
                return chr(int(entity[2:], 16))
            except (ValueError, OverflowError):
                return match.group(0)

        # Check for decimal entities (&#...;)
        elif entity.startswith('#'):
            try:
                # Extract decimal value and convert to integer, then to character
                return chr(int(entity[1:]))
            except (ValueError, OverflowError):
                return match.group(0)

        # Handle named entities
        else:
            return named_entities.get(entity, match.group(0))

    # Regular expression pattern:
    # & matches the literal '&'
    # ( ... ) capturing group 1 for the entity body
    # #(?:[xX][0-9a-fA-F]+|[0-9]+) matches numeric entities (hex or decimal)
    # | [a-zA-Z0-9]+ matches alphanumeric named entities
    # ; matches the literal ';'
    pattern = r'&(#(?:[xX][0-9a-fA-F]+|[0-9]+)|[a-zA-Z0-9]+);'

    return re.sub(pattern, replace_entity, s)

