    for pair in pairs:
        if not pair:
            continue

        # Split key and value
        if '=' in pair:
            k_raw, v_raw = pair.split('=', 1)
        else:
            k_raw, v_raw = pair, ''

        # Percentage-decode key and value
        key = urllib.parse.unquote_plus(k_raw)
        value = urllib.parse.unquote_plus(v_raw)

        # Parse nested key structure (e.g., "filters[price][lt]" -> ["filters", "price", "lt"])
        # This regex finds all sequences of characters that are not brackets
        parts = re.findall(r'([^\[\]]+)', key)

        if not parts:
            continue

        # Traverse/build the nested dictionary structure
        current = result
        for i in range(len(parts) - 1):
            part = parts[i]
            # If the path doesn't exist or is not a dict (conflict), overwrite with a dict
            if part not in current or not isinstance(current[part], dict):
                current[part] = {}
            current = current[part]

        # Handle the final key in the path
        last_key = parts[-1]
        if last_key in current:
            existing = current[last_key]
            if isinstance(existing, list):
                existing.append(value)
            else:
                # Convert single value to a list to handle duplicate keys
                current[last_key] = [existing, value]
        else:
            current[last_key] = value

    return result
