class WildcardTrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class WildcardTrie:
    def __init__(self):
        self.root = WildcardTrieNode()

    def insert(self, word: str) -> None:
        """
        Inserts a word into the trie.
        """
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = WildcardTrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word: str) -> bool:
        """
        Returns if the word is in the trie. 
        The character '.' can be used as a wildcard to match any single character.
        """
        def dfs(node, index):
            # Base case: reached the end of the search word
            if index == len(word):
                return node.is_end_of_word

            char = word[index]

            if char == '.':
                # Wildcard case: check all possible children at this level
                for child in node.children.values():
                    if dfs(child, index + 1):
                        return True
                return False
            else:
                # Specific character case: follow the path if it exists
                if char in node.children:
                    return dfs(node.children[char], index + 1)
                return False

        return dfs(self.root, 0)

