class Node:
    def __init__(self, val, color="RED"):
        self.val = val
        self.color = color
        self.left = None
        self.right = None
        self.parent = None

class RedBlackTree:
    def __init__(self):
        # NIL node is a sentinel representing all leaves
        # In RBT, all leaves (NIL) are considered BLACK
        self.NIL = Node(None, color="BLACK")
        self.root = self.NIL

    def _left_rotate(self, x):
        y = x.right
        x.right = y.left
        if y.left != self.NIL:
            y.left.parent = x

        y.parent = x.parent
        if x.parent == None:
            self.root = y
        elif x == x.parent.left:
            x.parent.left = y
        else:
            x.parent.right = y

        y.left = x
        x.parent = y

    def _right_rotate(self, x):
        y = x.left
        x.left = y.right
        if y.right != self.NIL:
            y.right.parent = x

        y.parent = x.parent
        if x.parent == None:
            self.root = y
        elif x == x.parent.right:
            x.parent.right = y
        else:
            x.parent.left = y

        y.right = x
        x.parent = y

    def insert(self, val):
        # Standard BST Insertion
        new_node = Node(val)
        new_node.left = self.NIL
        new_node.right = self.NIL

        y = None
        x = self.root

        while x != self.NIL:
            y = x
            if new_node.val < x.val:
                x = x.left
            else:
                x = x.right

        new_node.parent = y
        if y == None:
            self.root = new_node
        elif new_node.val < y.val:
            y.left = new_node
        else:
            y.right = new_node

        # Fix Red-Black Tree properties
        self._insert_fixup(new_node)

    def _insert_fixup(self, k):
        while k.parent and k.parent.color == "RED":
            if k.parent == k.parent.parent.left:
                uncle = k.parent.parent.right
                if uncle.color == "RED":
                    # Case 1: Uncle is RED
                    k.parent.color = "BLACK"
                    uncle.color = "BLACK"
                    k.parent.parent.color = "RED"
                    k = k.parent.parent
                else:
                    # Case 2: Uncle is BLACK, k is right child
                    if k == k.parent.right:
                        k = k.parent
                        self._left_rotate(k)
                    # Case 3: Uncle is BLACK, k is left child
                    k.parent.color = "BLACK"
                    k.parent.parent.color = "RED"
                    self._right_rotate(k.parent.parent)
            else:
                uncle = k.parent.parent.left
                if uncle.color == "RED":
