                    k.parent.color = "BLACK"
                    uncle.color = "BLACK"
                    k.parent.parent.color = "RED"
                    k = k.parent.parent
                else:
                    # Case 2: Uncle is BLACK, k is left child
                    if k == k.parent.left:
                        k = k.parent
                        self._right_rotate(k)
                    # Case 3: Uncle is BLACK, k is right child
                    k.parent.color = "BLACK"
                    k.parent.parent.color = "RED"
                    self._left_rotate(k.parent.parent)

            if k == self.root:
                break

        self.root.color = "BLACK"

    def is_valid_rbt(self) -> bool:
        if self.root == self.NIL:
            return True

        # Property 1: Root must be black
        if self.root.color != "BLACK":
            return False

        # Property 2: No red-red violations
        if not self._check_no_red_red(self.root):
            return False

        # Property 3: Constant black height for all paths
        try:
            self._check_black_height(self.root)
            return True
        except ValueError:
            return False

    def _check_no_red_red(self, node):
        if node == self.NIL:
            return True

        if node.color == "RED":
            if node.left.color == "RED" or node.right.color == "RED":
                return False

        return self._check_no_red_red(node.left) and self._check_no_red_red(node.right)

    def _check_black_height(self, node):
        if node == self.NIL:
            return 1

        left_h = self._check_black_height(node.left)
        right_h = self._check_black_height(node.right)

        if left_h != right_h:
            raise ValueError("Black height mismatch")

        return left_h + (1 if node.color == "BLACK" else 0)

