import heapq

def bidirectional_dijkstra(graph: dict, start: str, end: str) -> tuple[float, list[str]]:
    """
    Finds the shortest path between start and end nodes in a weighted graph 
    using the bidirectional Dijkstra's algorithm.
    """
    if start == end:
        return 0.0, [start]

    # Precompute reverse graph to allow backward search in directed graphs
    rev_graph = {}
    for u in graph:
        for v, w in graph[u]:
            if v not in rev_graph:
                rev_graph[v] = []
            rev_graph[v].append((u, w))

    # Priority queues for forward and backward searches
    # Stores tuples of (distance, node_name)
    pq_f = [(0.0, start)]
    pq_b = [(0.0, end)]

    # Distances from start and end
    dist_f = {start: 0.0}
    dist_b = {end: 0.0}

    # Parents for path reconstruction
    parent_f = {start: None}
    parent_b = {end: None}

    # Visited sets to avoid reprocessing nodes
    visited_f = set()
    visited_b = set()

    # mu stores the cost of the shortest path found so far
    mu = float('inf')
    best_node = None

    while pq_f and pq_b:
        # Expand the frontier with the smaller priority queue to balance the search
        if len(pq_f) <= len(pq_b):
            d, u = heapq.heappop(pq_f)
            if u in visited_f:
                continue
            visited_f.add(u)

            # Relax neighbors in forward search
            for v, w in graph.get(u, []):
                new_dist = dist_f[u] + w
                if v not in dist_f or new_dist < dist_f[v]:
                    dist_f[v] = new_dist
                    parent_f[v] = u
                    heapq.heappush(pq_f, (new_dist, v))
                    # If v has been reached by the backward search, update the best path found
                    if v in dist_b:
                        if dist_f[v] + dist_b[v] < mu:
                            mu = dist_f[v] + dist_b[v]
                            best_node = v
        else:
            d, u = heapq.heappop(pq_b)
            if u in visited_b:
                continue
            visited_b.add(u)

            # Relax neighbors in backward search (using reverse graph)
            for v, w in rev_graph.get(u, []):
                new_dist = dist_b[u] + w
                if v not in dist_b or new_dist < dist_b[v]:
                    dist_b[v] = new_dist
                    parent_b[v] = u
                    heapq.heappush(pq_b, (new_dist, v))
                    # If v has been reached by the forward search, update the best path found
                    if v in dist_f:
                        if dist_f[v] + dist_b[v] < mu:
                            mu = dist_f[v] + dist_b[v]
                            best_node = v

        # Termination condition: if the sum of the minimum distances in both queues 
        # is at least mu, no shorter path can be found.
        if pq_f and pq_b:
            if pq_f[0][0] + pq_b[0][0] >= mu:
                break

    # If no path was found
    if best_node is None:
        return float('inf'), []

    # Reconstruct the path from start to end via best_node
    path = []

    # Forward path: start -> ... -> best_node
    curr = best_node
    while curr is not None:
        path.append(curr)
        curr = parent_f[curr]
    path.reverse()

    # Backward path: best_node -> ... -> end
    # start from the node that leads from best_node towards the end
    curr = parent_b[best_node]
    while curr is not None:
        path.append(curr)
        curr = parent_b[curr]

    return float(mu), path

