import math

class ExactFraction:
    """
    A custom rational number class that represents a fraction in its lowest terms.
    """

    def __init__(self, numerator, denominator=1):
        if denominator == 0:
            raise ZeroDivisionError("Denominator cannot be zero.")

        # Ensure numerator and denominator are integers
        numerator = int(numerator)
        denominator = int(denominator)

        # Simplify the fraction by finding the greatest common divisor
        common = math.gcd(numerator, denominator)

        # Reduce to lowest terms
        num = numerator // common
        den = denominator // common

        # Ensure the denominator is always positive for consistency
        if den < 0:
            num = -num
            den = -den

        self.numerator = num
        self.denominator = den

    def __add__(self, other):
        if not isinstance(other, ExactFraction):
            if isinstance(other, int):
                other = ExactFraction(other)
            else:
                return NotImplemented

        # a/b + c/d = (ad + bc) / bd
        new_num = self.numerator * other.denominator + other.numerator * self.denominator
        new_den = self.denominator * other.denominator
        return ExactFraction(new_num, new_den)

    def __sub__(self, other):
        if not isinstance(other, ExactFraction):
            if isinstance(other, int):
                other = ExactFraction(other)
            else:
                return NotImplemented

        # a/b - c/d = (ad - bc) / bd
        new_num = self.numerator * other.denominator - other.numerator * self.denominator
        new_den = self.denominator * other.denominator
        return ExactFraction(new_num, new_den)

    def __mul__(self, other):
        if not isinstance(other, ExactFraction):
            if isinstance(other, int):
                other = ExactFraction(other)
            else:
                return NotImplemented

        # (a/b) * (c/d) = (ac) / (bd)
        new_num = self.numerator * other.numerator
        new_den = self.denominator * other.denominator
        return ExactFraction(new_num, new_den)

    def __truediv__(self, other):
        if not isinstance(other, ExactFraction):
            if isinstance(other, int):
                other = ExactFraction(other)
            else:
                return NotImplemented

        if other.numerator == 0:
            raise ZeroDivisionError("Cannot divide by a fraction with a numerator of zero.")

        # (a/b) / (c/d) = (ad) / (bc)
        new_num = self.numerator * other.denominator
        new_den = self.denominator * other.numerator
        return ExactFraction(new_num, new_den)

    def __eq__(self, other):
        if not isinstance(other, ExactFraction):
            if isinstance(other, int):
                other = ExactFraction(other)
            else:
                return False
        return self.numerator == other.numerator and self.denominator == other.denominator

    def __str__(self):
        if self.denominator == 1:
            return str(self.numerator)
        return f"{self.numerator}/{self.denominator}"

    def __repr__(self):
        return f"ExactFraction({self.numerator}, {self.denominator})"

