import math

def sparse_cosine_similarity(v1: dict, v2: dict) -> float:
    """
    Compute the Cosine Similarity between two sparse vectors represented as dictionaries.
    Optimized to only process overlapping non-zero dimensions for the dot product.
    """
    # Return 0.0 if either vector is empty
    if not v1 or not v2:
        return 0.0

    # Calculate dot product: iterate over the smaller dictionary to minimize lookups
    dot_product = 0.0
    if len(v1) < len(v2):
        for key, value in v1.items():
            if key in v2:
                dot_product += value * v2[key]
    else:
        for key, value in v2.items():
            if key in v1:
                dot_product += value * v1[key]

    # If vectors are orthogonal (no overlap), dot_product is 0.0
    if dot_product == 0:
        return 0.0

    # Calculate magnitudes (L2 norms)
    # Sum of squares for v1
    sum_sq1 = sum(value**2 for value in v1.values())
    # Sum of squares for v2
    sum_sq2 = sum(value**2 for value in v2.values())

    # Check for zero-magnitude vectors to avoid division by zero
    if sum_sq1 == 0 or sum_sq2 == 0:
        return 0.0

    # Cosine Similarity = (A . B) / (||A|| * ||B||)
    return dot_product / (math.sqrt(sum_sq1) * math.sqrt(sum_sq2))

