class GNode:
    def __init__(self):
        """
        Initialize a GNode with an empty list of reference links.
        """
        self.ref_to = []

    def add_ref(self, other):
        """
        Utility method to add a reference to another node.
        """
        self.ref_to.append(other)


def find_and_break_cycles(nodes: list[GNode]) -> int:
    """
    Identifies cycles of unreachable objects (nodes that cannot be reached from 
    any node outside the cycle) and breaks them by clearing their reference links.
    Returns the total number of links cleared.
    """
    if not nodes:
        return 0

    nodes_set = set(nodes)
    dfn = {}
    low = {}
    stack = []
    on_stack = set()
    sccs = []
    timer = 0

    # Iterative Tarjan's Algorithm to find Strongly Connected Components (SCCs)
    for start_node in nodes:
        if start_node not in dfn:
            # call_stack stores: (current_node, next_edge_index_to_visit)
            call_stack = [(start_node, 0)]
            while call_stack:
                u, pi = call_stack[-1]
                if pi == 0:
                    dfn[u] = low[u] = timer
                    timer += 1
                    stack.append(u)
                    on_stack.add(u)

                found_neighbor = False
                # Process neighbors starting from the last visited index
                for i in range(pi, len(u.ref_to)):
                    v = u.ref_to[i]
                    if v not in nodes_set:
                        continue  # Only track nodes within the provided universe
                    if v not in dfn:
                        # Update parent index and recurse into neighbor
                        call_stack[-1] = (u, i + 1)
                        call_stack.append((v, 0))
                        found_neighbor = True
                        break
                    elif v in on_stack:
                        low[u] = min(low[u], dfn[v])

                if not found_neighbor:
                    # After visiting all neighbors, check if u is the root of an SCC
                    if low[u] == dfn[u]:
                        scc = []
                        while True:
                            node = stack.pop()
                            on_stack.remove(node)
                            scc.append(node)
                            if node == u:
                                break
                        sccs.append(scc)
                    call_stack.pop()
                    if call_stack:
                        parent, _ = call_stack[-1]
                        low[parent] = min(low[parent], low[u])

    # Map every node to its SCC ID
    node_to_scc = {}
    for idx, scc in enumerate(sccs):
        for node in scc:
            node_to_scc[node] = idx

    # Determine if an SCC is reachable from any node outside itself
    scc_has_external_in = [False] * len(sccs)
    for u in nodes:
        u_scc = node_to_scc.get(u)
        if u_scc is None:
            continue
        for v in u.ref_to:
            v_scc = node_to_scc.get(v)
            if v_scc is not None and u_scc != v_scc:
                scc_has_external_in[v_scc] = True

    total_broken_links = 0
    nodes_to_clear = []

    # Identify isolated cycles (unreachable from outside)
    for scc in sccs:
        scc_id = node_to_scc[scc[0]]

        # An SCC is a cycle if it contains > 1 node, or 1 node with a self-loop
        is_cycle = False
        if len(scc) > 1:
            is_cycle = True
        elif len(scc) == 1:
            node = scc[0]
            if node in node.ref_to:
                is_cycle = True

        # If the cycle cannot be reached from any node outside the cycle
        if is_cycle and not scc_has_external_in[scc_id]:
            for node in scc:
                total_broken_links += len(node.ref_to)
                nodes_to_clear.append(node)

    # Break the cycles by clearing the reference lists
    for node in nodes_to_clear:
        node.ref_to = []

    return total_broken_links

